using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Minimal API")]
    [TestClass]
    public class RJIT_CR_MAPI_00009 : MinimalApiTestBase
    {
        [TestMethod]
        public void Each_Minimal_Api_Mapping_Must_Use_WithName_For_Client_Generation()
        {
            var invalidEndpointMappings = (from mapStatement in MapStatements
                                           where mapStatement.SyntaxTree.DoesNotContain(".WithName")
                                           select new
                                           {
                                               Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
FilePath:  {mapStatement.FilePath}
-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Syntax:    

{mapStatement.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{mapStatement.SyntaxTree.Replace("});", "}).WithName(\"getAllItems\");").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                           }).ToImmutableList();

            Assert.IsTrue(invalidEndpointMappings.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MAPI_00009

Please explicit declare the operation id (.WithName).This is necessary for any frontend client generation.
This is equivalent to the operationId in the OpenAPI specification. In controller implementations known as SwaggerOperationId

Findings {invalidEndpointMappings.Count}': 

{invalidEndpointMappings.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
